namespace nm=numi::matter; namespace assets=numi::human::registered_organic_tet_assets;
using V=std::array<double,3>;
static void ck(bool q,const std::string&m){if(!q)throw std::runtime_error(m);}
static V sub(V a,V b){return {a[0]-b[0],a[1]-b[1],a[2]-b[2]};}
static double dot(V a,V b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}
static V cross(V a,V b){return {a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}
static double vol6(V a,V b,V c,V d){return dot(sub(b,a),cross(sub(c,a),sub(d,a)));}
static std::string materialText(){return "material regional_contact_probe { parameter density : kg/m^3 = 1000 in [1000,1000]; parameter mu : Pa = 50000 in [50000,50000]; parameter lambda : Pa = 500000 in [500000,500000]; state diagnostic_memory : one = 0 transfer max; model neo_hookean; update diagnostic_memory = diagnostic_memory; energy = neo_hookean(mu,lambda); valid = J() - 0.1; supports fem; interface {static_friction=0;dynamic_friction=0;restitution=0;adhesion=0;} limits {minimum_J=0.1;maximum_J=10;maximum_stress=1e9;maximum_energy_density=1e9;} }";}
static nm::ObjectSource makeObject(const assets::Asset&a){nm::ObjectSource o;o.name="registered/right-kidney/FJ3147/fd-singleton-diagnostic";o.representation=nm::Representation::fem;o.materialIndex=0;o.twoWayCoupling=true;o.adaptive=false;o.mixedFEM=false;o.deformableContact=false;o.deformableSelfContact=false;o.characteristicLength=.03;o.femNodes.reserve(a.nodeCount);for(uint32_t i=0;i<a.nodeCount;i++)o.femNodes.push_back({a.nodes[i].local[0],a.nodes[i].local[1],a.nodes[i].local[2]});o.tetrahedra.reserve(a.tetCount);for(uint32_t i=0;i<a.tetCount;i++){auto t=a.tets[i].nodes;if(vol6(o.femNodes[t[0]],o.femNodes[t[1]],o.femNodes[t[2]],o.femNodes[t[3]])<0)std::swap(t[1],t[2]);o.tetrahedra.push_back({t});}o.femFixedNodes.push_back(0u);return o;}
static void advance(nm::Runtime&r,id<MTLCommandQueue>q,id<MTLBuffer>status){auto*s=static_cast<MRMetalWorldStatusGPU*>(status.contents);*s={};s->code=MR_STEP_SUCCESS;id<MTLCommandBuffer>c=[q commandBuffer];nm::EncodeRequest a{};a.commandBuffer=(__bridge void*)c;a.environmentStatuses=(__bridge void*)status;a.controlStep=0;a.physicsSubstep=0;a.physicsSubsteps=1;a.timestepSeconds=r.timestepSeconds();a.phase=nm::EncodePhase::preDynamics;auto e=r.encode(a);ck(e.encoded,"preDynamics: "+e.message);a.phase=nm::EncodePhase::postCommit;e=r.encode(a);ck(e.encoded,"postCommit: "+e.message);[c commit];[c waitUntilCompleted];ck(c.status==MTLCommandBufferStatusCompleted,"Metal command buffer failed");}
int main(int argc,char**argv){@autoreleasepool{try{ck(argc==2||(argc==3&&std::string(argv[2])=="--preflight"),"usage: fd-singleton-probe <MatterSource.metal> [--preflight]");constexpr double dt=.00025;const auto&A=assets::kRightKidney;nm::WorldSource ws;ws.environmentCount=1;ws.frameTimestep=dt;ws.gravity={0,0,-9.81};ws.mixedSolver.newtonIterations=12;ws.mixedSolver.fgmresIterations=64;auto parsed=nm::parseMatter(materialText());ck(parsed.succeeded(),"material parse failed");ws.materials.push_back(parsed.material);ws.objects.push_back(makeObject(A));ck(ws.objects.size()==1,"diagnostic must contain exactly one FEM object");ck(!ws.objects[0].deformableContact&&!ws.objects[0].deformableSelfContact,"contact must remain outside FD scope");nm::CompileOptions compileOptions;compileOptions.maximumRateExponent=0u;auto cw=nm::compileWorld(ws,compileOptions);ck(cw.world.dispatch.maximumRateExponent==0u,"diagnostic maximumRateExponent must be zero");std::string diag;for(const auto&d:cw.diagnostics)diag+=d.message+"; ";ck(cw.succeeded(),"compileWorld: "+diag);ck(cw.world.objects.size()==1&&cw.world.fem.tetrahedra.size()==A.tetCount,"compiled singleton layout mismatch");if(argc==3){std::cout<<"cpu_preflight={\"object_count\":"<<cw.world.objects.size()<<",\"nodes\":"<<A.nodeCount<<",\"tets\":"<<A.tetCount<<",\"dispatch_material_state_stride\":"<<cw.world.dispatch.materialStateStride<<",\"material_state_count\":"<<cw.world.materials.at(0).stateCount<<"}\n";return 0;}id<MTLDevice>d=MTLCreateSystemDefaultDevice();ck(d,"no Metal device");id<MTLCommandQueue>q=[d newCommandQueue];id<MTLBuffer>status=[d newBufferWithLength:sizeof(MRMetalWorldStatusGPU) options:MTLResourceStorageModeShared];ck(q&&status,"Metal allocation failed");nm::Runtime r;auto init=r.initialize(cw.world,{.metallib=std::filesystem::path(argv[1]),.environmentCount=1,.captureEvents=true,.captureDiagnostics=true,.automaticIdentification=false,.adaptiveTransfer=false});ck(init.encoded&&r.valid(),"runtime initialize: "+init.message);auto before=r.snapshot();ck(before.available,"initial snapshot unavailable");advance(r,q,status);auto after=r.snapshot();ck(after.available,"post-step snapshot unavailable");ck(after.statuses.size()==1,"missing status");std::cout.precision(17);std::cout<<"{\"case\":\"single_explicit_fem_operator_fd\",\"object_count\":"<<cw.world.objects.size()<<",\"nodes\":"<<A.nodeCount<<",\"tets\":"<<A.tetCount<<",\"self_contact\":false,\"deformable_contact\":false,\"fixed_reference_nodes\":1,\"gravity_m_s2\":[0,0,-9.81],\"dt_s\":"<<dt<<",\"newton_iterations\":12,\"fgmres_iterations\":64,\"status\":"<<after.statuses[0].code<<"}\n";ck(after.statuses[0].code==NM_STATUS_SUCCESS,"singleton mechanics step failed");}catch(const std::exception&e){std::cerr<<"fd_singleton_error={\"reason\":\""<<e.what()<<"\"}\n";return 1;}}return 0;}
